vector<int> countSmaller(vector<int>& a) {
    vector<int> v(a); sort(v.begin(), v.end()); v.erase(unique(v.begin(), v.end()), v.end()); int m = v.size(); vector<int> bit(m + 1, 0), out(a.size());
    for (int k = a.size() - 1; k >= 0; k--) { int r = lower_bound(v.begin(), v.end(), a[k]) - v.begin() + 1; int s = 0; for (int i = r - 1; i > 0; i -= i & -i) s += bit[i]; out[k] = s; for (int i = r; i <= m; i += i & -i) bit[i]++; }
    return out;
}
